const root="/home/axel/LeanAlgebraicGeometry-Horizon";
const cmds=[
 ["status","\"$HORIZON_GIT\" status --short -- MainProjects/Algebraic-Jacobian-Challenge-Rebuild MainProjects/Algebraic-Jacobian-Challenge"],
 ["tree_new","\"$HORIZON_GIT\" ls-tree -r --name-only HEAD -- MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/RelPicTensorStageFiniteStage.lean MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/Pic0CriticalPath.lean"],
 ["blob_match","\"$HORIZON_GIT\" show HEAD:MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/RelPicTensorStageFiniteStage.lean | diff -q - MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/RelPicTensorStageFiniteStage.lean; \"$HORIZON_GIT\" show HEAD:MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/Pic0CriticalPath.lean | diff -q - MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/Pic0CriticalPath.lean"],
 ["processes","ps -eo pid,ppid,etime,stat,rss,args | rg '/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild/' | rg 'lake|lean' | rg -v 'rg /LeanAlgebraicGeometry' | head -n 80"],
 ["heads","\"$HORIZON_GIT\" log -1 --format='%H%n%B'"]
];
const rs=await Promise.all(cmds.map(([n,c])=>tools.exec_command({cmd:c,workdir:root,yield_time_ms:10000,max_output_tokens:12000})));
rs.forEach((r,i)=>text(`### ${cmds[i][0]}\n${r.output}`));

